import{_ as e,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const A=JSON.parse('{"title":"简介 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"包含框架","slug":"包含框架","link":"#包含框架","children":[]},{"level":2,"title":"AJAX 请求如何工作","slug":"ajax-请求如何工作","link":"#ajax-请求如何工作","children":[]},{"level":2,"title":"用法示例","slug":"用法示例","link":"#用法示例","children":[]}],"relativePath":"2.x/zh-cn/ajax/introduction.md","filePath":"2.x/zh-cn/ajax/introduction.md"}'),i={name:"2.x/zh-cn/ajax/introduction.md"};function r(k,a,g,d,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"简介",-1)),s(p),a[1]||(a[1]=u(`<p>October CMS 包含一个框架，该框架带来了一整套AJAX功能，允许您从服务器加载数据而无需刷新浏览器页面。相同的库可用于<a href="./../cms/themes.html">CMS 主题</a> 和 <a href="./../backend/controllers-ajax.html#oc-using-ajax-handlers">后端管理区域</a>的任何地方.</p><p>AJAX 框架有两种风格，你可以使用 <a href="./../ajax/javascript-api.html">JavaScript API</a> 或 <a href="./../ajax/attributes-api.html">数据属性 API</a>。数据属性 API 不需要任何 JavaScript 知识即可在 October使用 AJAX。</p><p><a id="oc-including-the-framework"></a></p><h2 id="包含框架"><a href="#包含框架" class="header-anchor">#</a> 包含框架</h2><p>AJAX 框架在您的 <a href="./../cms/themes.html">CMS 主题</a>，要使用该库，您应该通过将&quot;{% framework %}&quot;标记放在 <a href="./../cms/pages.html">页面</a> 或 <a href="./../cms/layouts.html">布局</a>。这添加了对 October前端 JavaScript 库的引用。该库需要jQuery，因此应首先加载它，例如：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>assets/javascript/jquery.js<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>theme <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><code>{% framework %}</code> 标签支持可选的 <strong>extras</strong> 参数。 如果指定了此参数，该标签会为 <a href="./../ajax/extras.html">额外功能</a> 添加样式表和 JavaScript 文件，包括表单验证和加载指示符。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="ajax-请求如何工作"><a href="#ajax-请求如何工作" class="header-anchor">#</a> AJAX 请求如何工作</h2><p>页面可以通过数据属性提示或使用 JavaScript 发出 AJAX 请求。每个请求都会调用服务器上的 <strong>事件处理程序</strong> —— 也称为 <a href="./../ajax/handlers.html">AJAX 处理程序</a> —— 并且可以使用部件更新页面元素。 AJAX 请求最适合表单，因为表单数据会自动发送到服务器。这是请求工作流程：</p><ol><li>客户端浏览器通过提供处理程序名称和其他可选参数发出 AJAX 请求。</li><li>服务器找到<a href="./../ajax/handlers.html">AJAX handler</a>并执行。</li><li>处理程序执行所需的业务逻辑并通过注入页面变量更新环境。</li><li>客户端使用<code>update</code>选项请求服务器的<a href="./../ajax/update-partials.html">呈现部分</a>。</li><li>服务器发送响应，其中包含呈现部件标记。</li><li>客户端框架使用从服务器接收部件数据更新页面元素。</li></ol><blockquote><p><strong>注意</strong>：根据页面上下文，将呈现 <a href="./../cms/partials.html">CMS 部件</a> 或 <a href="./../backend/views-partials.html">后端部件</a> 视图。</p></blockquote><h2 id="用法示例"><a href="#用法示例" class="header-anchor">#</a> 用法示例</h2><p>下面是一个简单的例子，它使用数据属性 API 来定义一个支持 AJAX 的表单。该表单将向 <strong>onTest</strong> 处理程序发出 AJAX 请求，并请求使用 <strong>mypartial</strong> 部件标记更新结果容器。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- AJAX enabled form --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onTest<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mypartial: &#39;#myDiv&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- 输入两个值 --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span> + <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Action button --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>计算<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- 结果容器 --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>注意</strong>：<code>value1</code> 和 <code>value2</code> 的表单数据会随 AJAX 请求自动发送。</p></blockquote><p><strong>mypartial</strong> 部件包含读取 <code>result</code> 变量的标记。</p><div class="language-twig extra-class"><pre class="language-twig"><code>结果是 <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><strong>onTest</strong> 处理程序方法使用 <code>input</code> <a href="./../services/helper.html#method-input">助手方法</a> 访问表单数据，并将结果传递给 <code>result</code> 页面变量。</p><div class="language-php extra-class"><pre class="language-php"><code>函数 <span class="token function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
     <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>该示例可以这样读：&quot;提交表单时，向 <strong>onTest</strong> 处理程序发出 AJAX 请求。处理程序完成后，呈现 <strong>mypartial</strong> 部件并将其内容注入 <strong>#myDiv</strong> 元素。&quot;</p>`,21))])}const f=e(i,[["render",r]]);export{A as __pageData,f as default};
